type loginBucket struct {
	Count        int
	Reset        time.Time
	BlockedUntil time.Time
}
type LoginLimiter struct {
	mu      sync.Mutex
	buckets map[string]loginBucket

	Limit   int
	Window  time.Duration
	Block   time.Duration
}

func NewLoginLimiter() *LoginLimiter {
	return &LoginLimiter{buckets: map[string]loginBucket{}, Limit: 8, Window: 5 * time.Minute, Block: 15 * time.Minute}
}

func (l *LoginLimiter) Allow(key string) bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := time.Now()
	b := l.buckets[key]
	if now.Before(b.BlockedUntil) {
		return false
	}

if b.Reset.IsZero() || now.After(b.Reset) {
	b = loginBucket{Reset: now.Add(l.Window)}
}
b.Count++
if b.Count > l.Limit {
	b.BlockedUntil = now.Add(l.Block)
	l.buckets[key] = b
	return false

	}
	l.buckets[key] = b
	return true
}
